    private Mc263TrailRuinsGrammarData() {}

    static byte[] json() {
        byte[] compressed;
        try { compressed = Base64.getDecoder().decode(DATA); }
        catch (IllegalArgumentException error) {
            throw new IllegalStateException("corrupt Trail Ruins grammar encoding", error);
        }
        try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(compressed));
                ByteArrayOutputStream output = new ByteArrayOutputStream()) {
            gzip.transferTo(output);
            byte[] result = output.toByteArray();
            if (result.length < 100_000 || result.length > 4_000_000) {
                throw new IllegalStateException("Trail Ruins grammar length outside bound");
            }
            return result;
        } catch (IOException error) {
            throw new IllegalStateException("corrupt Trail Ruins grammar compression", error);
        }
    }

    static byte[] jigsawFinalStates() {
        byte[] compressed;
        try { compressed = Base64.getDecoder().decode(JIGSAW_FINAL_STATES); }
        catch (IllegalArgumentException error) {
            throw new IllegalStateException("corrupt Trail jigsaw final-state encoding", error);
        }
        try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(compressed));
                ByteArrayOutputStream output = new ByteArrayOutputStream()) {
            gzip.transferTo(output);
            byte[] result = output.toByteArray();
            if (result.length < 5_000 || result.length > 8_000) {
                throw new IllegalStateException("Trail jigsaw final-state grammar outside bound");
            }
            return result;
        } catch (IOException error) {
            throw new IllegalStateException("corrupt Trail jigsaw final-state compression", error);
        }
    }
